        raise ValueError("cents must be an int")
    is_negative = cents < 0
    abs_cents = abs(cents)
    dollars = abs_cents // 100
    cents_part = abs_cents % 100
    if dollars == 0:
        dollars_str = "0"
    else:
        dollars_str = format(dollars, ",d").replace(",", "")
        # Reinsert commas correctly
        parts = []
        while dollars_str:
            parts.append(dollars_str[-3:])
            dollars_str = dollars_str[:-3]
        dollars_str = ",".join(reversed(parts))
    cents_str = f"{cents_part:02d}"
    result = f"{dollars_str}.{cents_str}"
    if is_negative:
        result = "-" + result
    return result

