        return 0
    if text.startswith("--") or text.startswith("+-") or text.startswith("-+"):
        raise ValueError("invalid sign")
    parts = text.split(".")
    if len(parts) != 2:
        raise ValueError("missing decimal point")
    dollars_str, cents_str = parts
