        raise ValueError("invalid cents part")
    cents_value = int(cents_str)
    if dollars_str == "":
        raise ValueError("missing dollars part")
    if dollars_str == "0":
        if len(cents_str) != 2 or cents_value != 0:
            raise ValueError("invalid zero dollars")
        return 0 if text[0] != "-" else -0
    sign = 1
    if dollars_str.startswith("-"):
        if len(dollars_str) == 1:
            raise ValueError("invalid negative")
        sign = -1
        dollars_str = dollars_str[1:]
    # Remove commas and validate
    dollars_clean = dollars_str.replace(",", "")
    if not dollars_clean.isdigit():
        raise ValueError("invalid dollars part")
    if any(c == "," for c in dollars_str):
        # Check commas are properly placed
        segments = dollars_str.split(",")
        if any(len(s) != 3 for s in segments[1:]) or len(segments[0]) < 1 or len(segments[0]) > 3:
            raise ValueError("invalid commas")
    dollars_value = int(dollars_clean)
    total_cents = dollars_value * 100 + cents_value
    return sign * total_cents
