To solve the problem of converting between 12-hour and 24-hour time formats, we use precise regex validation to ensure the input conforms strictly to the required format. For `to_24h`, we validate the 12-hour format, split the hour, minute, and period, and adjust the hour based on AM/PM rules. For `to_12h`, we validate the 24-hour format, then map the hour to the appropriate 12-hour value and determine the AM/PM period. Both functions raise `ValueError` for invalid inputs.

```python
import re

def to_24h(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    match = re.fullmatch(r'([1-9]|1[0-2]):([0-5][0-9]) (AM|PM)', text)
    if not match:
        raise ValueError("Invalid 12-hour format.")
    hour_str, minute_str, period = match.groups()
    hour = int(hour_str)
    minute = int(minute_str)
    if period == 'AM':
        if hour == 12:
            new_hour = 0
        else:
            new_hour = hour
    else:
        if hour == 12:
            new_hour = 12
        else:
            new_hour = hour + 12
    return f"{new_hour:02d}:{minute:02d}"

def to_12h(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    match = re.fullmatch(r'([0-1][0-9]|2[0-3]):([0-5][0-9])', text)
    if not match:
        raise ValueError("Invalid 24-hour format.")
    hour_str, minute_str = match.groups()
    hour = int(hour_str)
    minute = int(minute_str)
    if hour == 0:
        return f"12:{minute:02d} AM"
    elif 1 <= hour < 12:
        return f"{hour}:{minute:02d} AM"
    elif hour == 12:
        return f"12:{minute:02d} PM"
    else:
        new_hour = hour - 12
        return f"{new_hour}:{minute:02d} PM"
