To implement the Luhn algorithm, we first validate the input strings to ensure they contain only digits and meet the required length. For `luhn_valid`, we reverse the digits, double every other digit starting from the second position (index 1 in the reversed list), adjust values over 9, and check if the sum is divisible by 10. For `luhn_append`, we calculate the required check digit by simulating the Luhn sum with a placeholder check digit (0), determine the necessary adjustment to make the sum a multiple of 10, and append the resulting digit.

```python
def luhn_valid(number):
    if not isinstance(number, str) or len(number) < 2:
        raise ValueError("number must be a string of at least two digits")
    if not all(c.isdigit() for c in number):
        raise ValueError("number must contain only ASCII digits")
    digits = [int(c) for c in number]
    reversed_digits = digits[::-1]
    total = 0
    for i, d in enumerate(reversed_digits):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str) or len(partial) < 1:
        raise ValueError("partial must be a string of at least one digit")
    if not all(c.isdigit() for c in partial):
        raise ValueError("partial must contain only ASCII digits")
    # Compute the sum as if check digit is 0
    full = partial + '0'
    digits = [int(c) for c in full]
    reversed_digits = digits[::-1]
    total = 0
    for i, d in enumerate(reversed_digits):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    # Compute check digit to make total % 10 == 0
    check_digit = (10 - (total % 10)) % 10
    return partial + str(check_digit)
