def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("text must be a str")
    parts = text.split('&')
    result = []
    for part in parts:
        if not part:
            continue  # Skip empty parts? But according to the problem statement, empty parts raise ValueError
        if '=' not in part:
            raise ValueError
        if part.count('=') > 1:
            raise ValueError
        key_enc, value_enc = part.split('=')
        key = decode(key_enc)
        value = decode(value_enc)
        result.append((key, value))
    # Now check for empty parts? For example, if text is "a=1&&b=2", then parts is ["a=1", "", "b=2"], which would raise error for the empty part.
    # So in the code above, for part in parts:
    # if part is empty, we raise ValueError. But in the current code, the for loop skips empty parts? No, because in the for loop, part can be empty. So in the first if not part: continue would skip it, leading to that part not being processed. But according to the problem statement, empty parts (like from "a=1&&b=2") should raise ValueError. So the code above is wrong. Need to check that each part is not empty.

    # So correct code is:
    result = []
    for part in parts:
        if not part:
            raise ValueError
        if '=' not in part:
            raise ValueError
        if part.count('=') > 1:
            raise ValueError
        key_enc, value_enc = part.split('=')
        key = decode(key_enc)
        value = decode(value_enc)
        result.append((key, value))
    return result

def decode(s):
    result = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '+':
            result.append(' ')
        elif c == '%':
            if i + 2 >= len(s):
                raise ValueError
            hex_part = s[i+1:i+3]
            try:
                code = int(hex_part, 16)
            except ValueError:
                raise ValueError
            if code > 0x7F:
                raise ValueError
            result.append(chr(code))
            i += 2  # Skip the next two characters
        else:
            if not (c.isalnum() or c in '-._~'):
                raise ValueError
            result.append(c)
        i += 1
    return ''.join(result)

def build_query(pairs):
    if not (isinstance(pairs, (list, tuple)) and all(isinstance(pair, tuple) and len(pair) == 2 for pair in pairs)):
        raise ValueError
    encoded_pairs = []
    for key, value in pairs:
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError
        if not key:
            raise ValueError
        # Check if all characters in key and value are ASCII
        for s in [key, value]:
            try:
                s.encode('ascii')
            except UnicodeEncodeError:
                raise ValueError
        encoded_key = encode(key)
