        for j in range(i + 1, n):
            x2, y2 = points[j]
            dx = x1 - x2
            dy = y1 - y2
            d2 = dx * dx + dy * dy
            if d2 < min_d2:
                min_d2 = d2
                best_i, best_j = i, j
    return (min_d2, best_i, best_j)

