```python
def manhattan_center(points):
    if not isinstance(points, (list, tuple)):
        raise ValueError
    if len(points) == 0:
        raise ValueError
    if len(points) > 100000:
        raise ValueError

    x_coords = []
    y_coords = []

    for p in points:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError
        x, y = p
        if type(x) is not int or type(y) is not int:
            raise ValueError
        if x is True or x is False or y is True or y is False:
            raise ValueError
        if not (-10**9 <= x <= 10**9) or not (-10**9 <= y <= 10**9):
            raise ValueError
        x_coords.append(x)
        y_coords.append(y)

    x_sorted = sorted(x_coords)
    y_sorted = sorted(y_coords)

    n = len(points)
    median_x = x_sorted[(n - 1) // 2]
    median_y = y_sorted[(n - 1) // 2]

    total = 0
    for x, y in points:
        total += abs(x - median_x) + abs(y - median_y)

    return (median_x, median_y, total)
