from collections import deque

def tree_centers(n, edges):
    if not isinstance(n, int) or n < 1 or n > 100000:
        raise ValueError
    if not isinstance(edges, (list, tuple)) or len(edges) != n - 1:
        raise ValueError
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError
        a, b = e
        if not (isinstance(a, int) and isinstance(b, int)):
            raise ValueError
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        parent = [-1] * n
        dist = [-1] * n
        q = deque([start])
        dist[start] = 0
        farthest = start
        max_dist = 0
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    q.append(neighbor)
                    if dist[neighbor] > max_dist:
                        max_dist = dist[neighbor]
                        farthest = neighbor
        return farthest, parent, dist

    u, _, _ = bfs(0)
    v, parent, dist = bfs(u)
    D = dist[v]

    # Reconstruct path from u to v
    path = []
    current = v
    while current != -1:
        path.append(current)
        current = parent[current]
    path.reverse()

    if D % 2 == 0:
        mid = D // 2
        centers = [path[mid]]
    else:
        mid1 = D // 2
        mid2 = mid1 + 1
        centers = [path[mid1], path[mid2]]
    centers.sort()
    return (centers, (D + 1) // 2)

