To implement the `elevator_stops` function using the LOOK algorithm, we first validate inputs and process requests in three phases: serving requests at the current floor, then same-direction requests, and finally opposite-direction requests. Unique requests are filtered and sorted appropriately for each phase. The total distance is computed as the cumulative absolute difference between consecutive floors.

```python
def elevator_stops(start, requests, direction):
    if not isinstance(start, int) or not (0 <= start <= 1000):
        raise ValueError
    if direction not in ("up", "down"):
        raise ValueError
    if not isinstance(requests, (list, tuple)):
        raise ValueError
    for r in requests:
        if not (isinstance(r, int) and not isinstance(r, bool)) or not (0 <= r <= 1000):
            raise ValueError
    if not requests:
        return ([], 0)

    unique_requests = set(requests)
    same_floor = [start] if start in unique_requests else []
    up_requests = []
    down_requests = []

    for r in unique_requests:
        if r > start:
            up_requests.append(r)
        elif r < start:
            down_requests.append(r)

    if direction == "up":
        up_sorted = sorted(up_requests)
        down_sorted = sorted(down_requests, reverse=True)
    else:  # direction == "down"
        down_sorted = sorted(down_requests)
        up_sorted = sorted(up_requests, reverse=True)

    if direction == "up":
        same_direction = up_sorted
        opposite_direction = down_sorted
    else:
        same_direction = down_sorted
        opposite_direction = up_sorted

    stops = same_floor
    if same_direction:
        stops += same_direction
    if opposite_direction:
        stops += opposite_direction

    distance = 0
    prev = start
    for floor in stops:
        distance += abs(floor - prev)
        prev = floor

    return (stops, distance)
