        '--...': '7', '---..': '8', '----.': '9'
    }

    if not isinstance(code, str):
        raise ValueError("code must be a string")

    if not code:
        return ""

    words = code.split(' / ')
    if any(word == '' for word in words):
        raise ValueError("Invalid Morse code: empty word")

    for word in words:
        codes = word.split()
        for c in codes:
            if c not in inverse_morse:
                raise ValueError(f"Invalid Morse code: {c}")

    result = []
    for word in words:
