        raise ValueError("Invalid format")

    # Split into sign and the rest
    if text.startswith('-'):
        sign = -1
        text = text[1:]
    else:
        sign = 1

    # Split into dollars and cents parts
    try:
        dollars_part, cents_part = text.split('.')
    except ValueError:
        raise ValueError("Invalid format")

    # Check cents part
    if len(cents_part) != 2:
        raise ValueError("Invalid cents part")
    if not cents_part.isdigit():
        raise ValueError("Invalid cents part")

    # Check dollars part
    if dollars_part == '0':
        dollars = 0
    else:
        # Remove commas and check if it's a valid integer
        if not re.match(r'^\d+$', dollars_part.replace(',', '')):
