def stair_ways(n, steps, broken):
    MOD = 1000000007

    # Validation
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 0 or n > 100000:
        raise ValueError

    if not isinstance(steps, (list, tuple, set)):
        raise ValueError
    if len(steps) < 1 or len(steps) > 10:
        raise ValueError
    steps_list = list(steps)
    for s in steps_list:
        if not isinstance(s, int) or isinstance(s, bool):
            raise ValueError
        if s < 1 or s > 100:
            raise ValueError
    if len(set(steps_list)) != len(steps_list):
        raise ValueError

    if not isinstance(broken, (list, tuple, set)):
        raise ValueError
    for b in broken:
        if not isinstance(b, int) or isinstance(b, bool):
            raise ValueError
        if n == 0:
            if b >= 0:
                raise ValueError
        else:
            if b < 1 or b > n - 1:
                raise ValueError

    # Handle n == 0 case
    if n == 0:
        return 1

    # Convert broken to a set for O(1) lookups
    broken_set = set(broken)

    # Initialize DP array
    ways = [0] * (n + 1)
    ways[0] = 1  # Base case

    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
            continue
        total = 0
        for s in steps_list:
            if s > i:
                continue
            total = (total + ways[i - s]) % MOD
        ways[i] = total % MOD

    return ways[n] % MOD

