def snake_to_camel(name):
    if not isinstance(name, str):
        raise ValueError("Invalid type for name")
    snake_pattern = r'^[a-z][a-z0-9_]*$'
    if not re.fullmatch(snake_pattern, name):
        parts = name.split('_')
        if len(parts) < 1 or not parts[0] or any(not part for part in parts) or '__' in name or name.startswith('_') or name.endswith('_'):
