    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = dp[i+1][j+1] + 1
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])

    i = j = 0
    result = []

    while i < m and j < n:
        if a[i] == b[j]:
            result.append(a[i])
            i += 1
            j += 1
        else:
            down = dp[i+1][j]
            right = dp[i][j+1]
            if down > right:
                i += 1
            elif right > down:
                j += 1
            else:
                # Generate all possible characters in both a[i:] and b[j:], sorted lex
                candidates = set()
                for k in range(i, m):
                    candidates.add(a[k])
                for k in range(j, n):
