    if not isinstance(start, int) or not (0 <= start <= 1000):
        raise ValueError
    if direction not in ('up', 'down'):
        raise ValueError
    if not isinstance(requests, (list, tuple)):
        raise ValueError
    for req in requests:
        if not isinstance(req, int) or not (0 <= req <= 1000):
            raise ValueError

    unique_requests = set(requests)
    if not unique_requests:
        return ([], 0)

    stops = []
    current_floor = start
    distance = 0

    # Serve current floor if requested
    if current_floor in unique_requests:
        stops.append(current_floor)
        unique_requests.remove(current_floor)

    # Process current direction requests
    if direction == 'up':
        curr_dir_requests = [f for f in unique_requests if f > current_floor]
        curr_dir_requests.sort()
        for floor in curr_dir_requests:
            stops.append(floor)
            distance += floor - current_floor
            current_floor = floor
    else:  # 'down'
        curr_dir_requests = [f for f in unique_requests if f < current_floor]
        curr_dir_requests.sort(reverse=True)
        for floor in curr_dir_requests:
            stops.append(floor)
            distance += current_floor - floor
            current_floor = floor

    # Process opposite direction requests
    if direction == 'up':
        opp_dir_requests = [f for f in unique_requests if f < current_floor]
        opp_dir_requests.sort(reverse=True)
    else:
        opp_dir_requests = [f for f in unique_requests if f > current_floor]
        opp_dir_requests.sort()

    for floor in opp_dir_requests:
        stops.append(floor)
        distance += abs(floor - current_floor)
        current_floor = floor

    return (stops, distance)

