def chain_order(dims):
    if not isinstance(dims, (list, tuple)):
        raise ValueError
    n = len(dims)
    if n < 2 or n > 27:
        raise ValueError
    for x in dims:
        if not (isinstance(x, int) and type(x) is int):
            raise ValueError
    if any(x < 1 or x > 1000 for x in dims):
        raise ValueError

    m = n - 1
    if m == 0:
        raise ValueError

    cost = [[0] * m for _ in range(m)]
    split = [[0] * m for _ in range(m)]

    for L in range(2, m + 1):
        for i in range(m - L + 1):
            j = i + L - 1
            cost[i][j] = float('inf')
            for s in range(i, j):
                c = cost[i][s] + cost[s+1][j] + dims[i] * dims[s+1] * dims[j+1]
                if c < cost[i][j]:
                    cost[i][j] = c
                    split[i][j] = s
                elif c == cost[i][j] and s < split[i][j]:
                    split[i][j] = s

    def build_order(i, j):
        if i == j:
            return chr(ord('A') + i)
        s = split[i][j]
        left = build_order(i, s)
        right = build_order(s+1, j)
        return f'({left}{right})'

    if m == 1:
        return (0, 'A')
    return (cost[0][m-1], build_order(0, m-1))

