To fix this, the `build_query` function should:
1. **Validate ASCII compliance**: Ensure all characters in keys and values are ASCII (i.e., `ord(c) <= 127`).
2. **Remove the `allowed_chars` validation**: This set is irrelevant for input validation. The allowed characters (A-Z, a-z, 0-9, "-._~") are only for encoding decisions, not validation.
3. **Correctly encode all non-allowed ASCII characters**: These should be percent-encoded, not rejected.

Here is the corrected implementation:

```python
def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    parts = text.split('&')
    result = []

    for part in parts:
        if not part:
            raise ValueError("Empty part in query")
        if part.count('=') != 1:
            raise ValueError("Part must contain exactly one '='")
        key, value = part.split('=', 1)
        if not key:
            raise ValueError("Key cannot be empty")

        def url_decode(s):
            decoded = []
            i = 0
            while i < len(s):
                if s[i] == '+':
                    decoded.append(' ')
                    i += 1
                elif s[i] == '%':
                    if i + 2 >= len(s):
                        raise ValueError("Incomplete percent escape")
                    hex_part = s[i+1:i+3]
                    if not all(c in '0123456789abcdefABCDEF' for c in hex_part):
                        raise ValueError("Invalid hex digits")
                    try:
                        byte = int(hex_part, 16)
                    except ValueError:
                        raise ValueError("Invalid hex value")
                    if byte > 0x7F:
                        raise ValueError("Byte value exceeds 0x7F")
                    decoded.append(chr(byte))
                    i += 3
                else:
                    decoded.append(s[i])
                    i += 1
            return ''.join(decoded)

        decoded_key = url_decode(key)
        decoded_value = url_decode(value)
        result.append((decoded_key, decoded_value))

    return result

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("pairs must be a list or tuple")

    def url_encode(s):
        encoded = []
        for c in s:
            if c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~":
                encoded.append(c)
            elif c == ' ':
                encoded.append('+')
            else:
                encoded.append(f"%{ord(c):02X}")
        return ''.join(encoded)

    for pair in pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("Each element must be a 2-tuple")
        key, value = pair
        if not isinstance(key, str) or not key:
            raise ValueError("Key must be a non-empty string")
        if not isinstance(value, str):
            raise ValueError("Value must be a string")
        for c in key:
            if ord(c) > 127:
                raise ValueError(f"Non-ASCII character '{c}' in key")
        for c in value:
            if ord(c) > 127:
                raise ValueError(f"Non-ASCII character '{c}' in value")

    encoded_pairs = []
    for key, value in pairs:
        encoded_key = url_encode(key)
        encoded_value = url_encode(value)
        encoded_pairs.append(f"{encoded_key}={encoded_value}")

    return '&'.join(encoded_pairs)
